        private static void MigrateLayout(ConfigFile c)
        {
            Dictionary<ConfigDefinition, string> orphans;
            try { orphans = Traverse.Create(c).Property("OrphanedEntries").GetValue<Dictionary<ConfigDefinition, string>>(); }
            catch (System.Exception e) { orphans = null; HandsAreHighPlugin.Log.LogWarning($"Config layout: old settings can't be read ({e.Message}); old values stay in the file, new keys start at their defaults"); }
            if (orphans == null || orphans.Count == 0) return;
            int moved = 0, kept = 0;
            foreach (string[] m in Moves)
            {
                var from = new ConfigDefinition(m[0], m[1]);
                if (!orphans.TryGetValue(from, out string value)) continue;
                orphans.Remove(from);
                var to = new ConfigDefinition(m[2], m[3]);
                if (orphans.ContainsKey(to) || c.ContainsKey(to)) { kept++; continue; }
                orphans[to] = value;
                moved++;
            }
            var merged = new List<string>(3);
            // Hands behind the head: laced won over one-over-the-other; both off = side by side.
            Merge(c, orphans, merged, new ConfigDefinition("6. Animations", "Hands behind head"),
                new ConfigDefinition("27. Hand-off, interact key, kneel variants", "Hands behind head: fingers laced"), new ConfigDefinition("27. Hand-off, interact key, kneel variants", "Hands behind head: one over the other"),
                (laced, over) => !Flag(laced, true) ? (Flag(over, true) ? HandsStyle.OneOverTheOther : HandsStyle.SideBySide).ToString() : HandsStyle.Laced.ToString());
            // Number keys: the numpad only ever worked with the top row on.
            Merge(c, orphans, merged, new ConfigDefinition("5. Commands and dialogue", "Number keys"),
                new ConfigDefinition("10. Orders", "Number keys give orders"), new ConfigDefinition("10. Orders", "Numpad keys too"),
                (top, pad) => !Flag(top, true) ? NumberKeysMode.Off.ToString() : Flag(pad, true) ? NumberKeysMode.Numpad.ToString() : NumberKeysMode.TopRow.ToString());
            // Flight distance: both were only ever used as the larger of the two.
            Merge(c, orphans, merged, new ConfigDefinition("4. Prisoner escape and recovery", "Flee distance from captivity (m)"),
                new ConfigDefinition("07. Retreat and recapture", "Leaves the captivity area (m)"), new ConfigDefinition("26. Release and escape", "Escape ends this far from the threat (m)"),
                (a, b) => System.Math.Max(Number(a, 40f), Number(b, 40f)).ToString(CultureInfo.InvariantCulture));
            // Lines left in the old sections are settings earlier versions removed (0.9.0 "Within
            // (m)", 0.21.0 captor cover, ...): nothing reads them, they only cluttered the file.
            var oldSections = new HashSet<string>();
            foreach (string[] m in Moves) oldSections.Add(m[0]);
            var stale = new List<ConfigDefinition>();
            foreach (ConfigDefinition d in orphans.Keys) if (oldSections.Contains(d.Section)) stale.Add(d);
            foreach (ConfigDefinition d in stale) orphans.Remove(d);
            if (moved + kept + merged.Count + stale.Count > 0)
                HandsAreHighPlugin.Log.LogInfo($"Config layout: {moved} saved value(s) moved to the new F12 sections" +
                    $"{(kept > 0 ? $", {kept} old line(s) dropped (the new key already had a value)" : "")}" +
                    $"{(stale.Count > 0 ? $", {stale.Count} line(s) of settings removed in earlier versions dropped" : "")}" +
                    $"{(merged.Count > 0 ? "; combined: " + string.Join("; ", merged) : "")}");
        }

        private static void Merge(ConfigFile c, Dictionary<ConfigDefinition, string> orphans, List<string> merged, ConfigDefinition to,
                                  ConfigDefinition a, ConfigDefinition b, System.Func<string, string, string> combine)
        {
            bool hasA = orphans.TryGetValue(a, out string va), hasB = orphans.TryGetValue(b, out string vb);
            if (!hasA && !hasB) return;
            orphans.Remove(a);
            orphans.Remove(b);
            if (orphans.ContainsKey(to) || c.ContainsKey(to)) return;
            string v = combine(hasA ? va : null, hasB ? vb : null);
            orphans[to] = v;
            merged.Add($"{a.Key} {va ?? "-"} + {b.Key} {vb ?? "-"} -> {to.Key} {v}");
        }

        private static bool Flag(string s, bool fallback) => s == null ? fallback : bool.TryParse(s.Trim(), out bool v) ? v : fallback;

        private static float Number(string s, float fallback) =>
            s != null && float.TryParse(s.Trim(), NumberStyles.Float, CultureInfo.InvariantCulture, out float v) ? v : fallback;
    }

    internal enum HandsStyle { Laced, OneOverTheOther, SideBySide }

    internal enum NumberKeysMode { Off, TopRow, Numpad }
}
